BEGIN;
INSERT INTO auth.users(id,email,raw_user_meta_data) SELECT ('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'commerce-'||n||'@tani.invalid',jsonb_build_object('name','Commerce test '||n,'phone','08123456'||n) FROM generate_series(1,4)n;
INSERT INTO public.profiles(id,name,phone,role) SELECT ('b1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Commerce test '||n,'08123456'||n,CASE WHEN n=2 THEN 'seller' WHEN n=4 THEN 'support' ELSE 'customer' END FROM generate_series(1,4)n ON CONFLICT(id) DO UPDATE SET role=EXCLUDED.role;
INSERT INTO public.sellers(id,user_id,store_name,verification_status) VALUES('b2000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000002','Test store','approved');
INSERT INTO public.merchant_profiles(user_id,seller_id,business_name,verification_status) VALUES('b1000000-0000-4000-8000-000000000002','b2000000-0000-4000-8000-000000000001','Test merchant','approved');
INSERT INTO public.products(id,seller_id,name,price,stock) VALUES('b4000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','Test product',100,10);
INSERT INTO public.delivery_zones(id,seller_id,area_name,fee,is_active) VALUES('b6000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','Test area',10,true);
INSERT INTO public.delivery_settings(seller_id,delivery_area,base_fee,is_active) VALUES('b2000000-0000-4000-8000-000000000001','Test area',10,true);
INSERT INTO public.addresses(id,user_id,label,description,phone) VALUES('b7000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001','Test home','Test area','0912345678');
INSERT INTO public.support_tickets(id,user_id,subject,description) VALUES('b8000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001','Test ticket','Test ticket details');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
DO $$ DECLARE q jsonb; g uuid; repeat_g uuid;
BEGIN
 q := public.quote_cart_v3('[{"product_id":"b4000000-0000-4000-8000-000000000001","quantity":2}]','{"b2000000-0000-4000-8000-000000000001":"b6000000-0000-4000-8000-000000000001"}');
 g := public.checkout_create_order_group_v4('b7000000-0000-4000-8000-000000000001','0912345678','Test', '[{"product_id":"b4000000-0000-4000-8000-000000000001","quantity":2}]','b9000000-0000-4000-8000-000000000001','{"b2000000-0000-4000-8000-000000000001":"b6000000-0000-4000-8000-000000000001"}',(q->>'grand_total')::numeric,q->>'quote_token');
 -- Retry with an expired quote / missing address must return the original committed order.
 repeat_g := public.checkout_create_order_group_v4(null,'','','[]','b9000000-0000-4000-8000-000000000001','{}',null,null);
 PERFORM tests.assert_true(g=repeat_g,'checkout retry returns one order group');
 PERFORM tests.assert_true((SELECT count(*) FROM public.order_groups WHERE idempotency_key='b9000000-0000-4000-8000-000000000001')=1,'checkout creates no duplicate');
END $$;
SELECT tests.assert_true((SELECT stock FROM public.products WHERE id='b4000000-0000-4000-8000-000000000001')=8,'retry decrements stock only once');
SELECT tests.assert_true((public.send_support_ticket_message('b8000000-0000-4000-8000-000000000001','Customer message')).sender_id=auth.uid(),'ticket owner can reply');
SELECT set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000003',true);
SELECT tests.expect_denied($q$SELECT public.send_support_ticket_message('b8000000-0000-4000-8000-000000000001','Unrelated message')$q$,'unrelated customer cannot send to another ticket');
SELECT tests.expect_denied($q$SELECT public.submit_delivered_order_reviews((SELECT id FROM public.orders LIMIT 1),5,'Unrelated review')$q$,'unrelated customer cannot review');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',true);
UPDATE public.orders SET status='delivered' WHERE customer_id='b1000000-0000-4000-8000-000000000001';
CREATE FUNCTION tests.fail_order_review() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Injected failure' USING ERRCODE='23514'; END $$;
CREATE TRIGGER test_review_failure BEFORE INSERT ON public.order_reviews FOR EACH ROW EXECUTE FUNCTION tests.fail_order_review();
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
DO $$ BEGIN
 BEGIN PERFORM public.submit_delivered_order_reviews((SELECT id FROM public.orders WHERE customer_id=auth.uid() LIMIT 1),5,'Test');
 EXCEPTION WHEN check_violation THEN RETURN; END;
 RAISE EXCEPTION 'Injected review failure was ignored';
END $$;
SELECT tests.assert_true((SELECT count(*) FROM public.reviews WHERE customer_id=auth.uid())=0 AND (SELECT count(*) FROM public.merchant_reviews WHERE customer_id=auth.uid())=0,'review failure rolls back all records');
RESET ROLE;
DROP TRIGGER test_review_failure ON public.order_reviews;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
SELECT tests.assert_true(public.submit_delivered_order_reviews((SELECT id FROM public.orders WHERE customer_id=auth.uid() LIMIT 1),5,'Test'),'delivered order reviews saved');
SELECT tests.assert_true(public.submit_delivered_order_reviews((SELECT id FROM public.orders WHERE customer_id=auth.uid() LIMIT 1),4,'Updated'),'review retry succeeds');
SELECT tests.assert_true((SELECT count(*) FROM public.reviews WHERE customer_id=auth.uid())=1 AND (SELECT count(*) FROM public.merchant_reviews WHERE customer_id=auth.uid())=1 AND (SELECT count(*) FROM public.order_reviews WHERE customer_id=auth.uid())=1,'review retry leaves exactly one complete set');
SELECT set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000004',true);
SELECT tests.assert_true((public.send_support_ticket_message('b8000000-0000-4000-8000-000000000001','Staff message')).sender_id=auth.uid(),'support can reply');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',true);
UPDATE public.reviews SET status='hidden' WHERE customer_id='b1000000-0000-4000-8000-000000000001';
UPDATE public.merchant_reviews SET status='hidden' WHERE customer_id='b1000000-0000-4000-8000-000000000001';
UPDATE public.support_tickets SET status='closed' WHERE id='b8000000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','b1000000-0000-4000-8000-000000000001',true);
SELECT public.submit_delivered_order_reviews((SELECT id FROM public.orders WHERE customer_id=auth.uid() LIMIT 1),5,'Updated hidden');
DO $$ BEGIN
 BEGIN PERFORM public.send_support_ticket_message('b8000000-0000-4000-8000-000000000001','Closed message');
 EXCEPTION WHEN check_violation THEN RETURN; END;
 RAISE EXCEPTION 'Closed ticket accepted a message';
END $$;
RESET ROLE;
SELECT tests.assert_true((SELECT bool_and(status='hidden') FROM public.reviews WHERE customer_id='b1000000-0000-4000-8000-000000000001') AND (SELECT bool_and(status='hidden') FROM public.merchant_reviews WHERE customer_id='b1000000-0000-4000-8000-000000000001'),'review retry preserves moderation');
ROLLBACK;
